import{_ as i,o as s,c as a,ao as t}from"./chunks/framework.Rf5RR52i.js";const g=JSON.parse('{"title":"Grids and cell indices","description":"","frontmatter":{},"headers":[],"relativePath":"abstractions.md","filePath":"abstractions.md","lastUpdated":null}'),r={name:"abstractions.md"};function n(o,e,l,d,c,p){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="Grids-and-cell-indices" tabindex="-1">Grids and cell indices <a class="header-anchor" href="#Grids-and-cell-indices" aria-label="Permalink to &quot;Grids and cell indices {#Grids-and-cell-indices}&quot;">​</a></h1><p>DiscreteGlobalGrids separates a grid&#39;s geometry from the values stored on it. These concepts also apply to regional grids and grids without a hierarchy.</p><h2 id="Grids-and-systems" tabindex="-1">Grids and systems <a class="header-anchor" href="#Grids-and-systems" aria-label="Permalink to &quot;Grids and systems {#Grids-and-systems}&quot;">​</a></h2><p>A <strong>grid</strong> is a finite collection of cells. An H3 grid at level 12 is a grid; so is a selected region of that level. Geometry, point queries and neighbourhood operations act on grids.</p><p>A <strong>system</strong> defines related grids at several levels, including their parent and child relationships. <code>levelgrid(sys, level)</code> selects one complete level. A grid can also supply its geometry directly, as an ocean-model grid might.</p><p>The <a href="./api/grid-interface">grid interface</a> documents both abstractions. <a href="./extending">Writing a grid system</a> implements a complete example, and the <a href="./architecture">architecture guide</a> describes the generic algorithms.</p><h2 id="Cell-ids-and-array-positions" tabindex="-1">Cell ids and array positions <a class="header-anchor" href="#Cell-ids-and-array-positions" aria-label="Permalink to &quot;Cell ids and array positions {#Cell-ids-and-array-positions}&quot;">​</a></h2><p>A <strong>cell id</strong> identifies a cell independently of the array that stores its value. A <strong>local index</strong> identifies a position in one collection. Selecting a region changes local positions while preserving cell ids.</p><p>A <code>Cells</code> dimension connects those identities to array values. Use it to <a href="./api/selecting-cells">select data by point or region</a>, while ordinary integer indexing selects positions in the current array.</p>',9)])])}const m=i(r,[["render",n]]);export{g as __pageData,m as default};
